String BAR = "" + (char) 124; String SEM = "" + (char) 59;
double dist(double a, double b, double c, double d) { double dy = (a - c) * 111320.0; double dx = (b - d) * 111320.0 * Math.cos(Math.toRadians(a)); return Math.sqrt(dx * dx + dy * dy); }
